// Parse WorldBank — fix: handle n8n split items
const rows = [];

// Helper: parse WorldBank response from node robustly
function extractLatestWB(items) {
  let dataArray = [];
  for (const item of items) {
    if (item.data) {
       let inner = typeof item.data === 'string' ? JSON.parse(item.data) : item.data;
       if (Array.isArray(inner) && Array.isArray(inner[1])) dataArray.push(...inner[1]);
       else if (Array.isArray(inner)) dataArray.push(...inner);
       else dataArray.push(inner);
    } else if (Array.isArray(item)) {
       if (Array.isArray(item[1])) dataArray.push(...item[1]);
       else dataArray.push(...item);
    } else {
       dataArray.push(item);
    }
  }
  return dataArray.find(r => r && r.value !== null && r.value !== undefined && r.value !== '');
}

// 1. Cereal Yield
let yieldItems = [];
try { yieldItems = $('Fetch Cereal Yield').all().map(i => i.json); } catch(e) {}
const yieldLatest = extractLatestWB(yieldItems);
if (yieldLatest) {
  rows.push({ source: 'WorldBank', commodity: 'Cereals', metric: 'cereal_yield', value: Math.round(yieldLatest.value * 100) / 100, unit: 'kg/ha', period: yieldLatest.date });
}

// 2. Cereal Production
let prodItems = [];
try { prodItems = $('Fetch Cereal Production').all().map(i => i.json); } catch(e) {}
const prodLatest = extractLatestWB(prodItems);
if (prodLatest) {
  rows.push({ source: 'WorldBank', commodity: 'Cereals', metric: 'cereal_production', value: Math.round(prodLatest.value), unit: 'tonnes', period: prodLatest.date });
}

if (rows.length === 0) {
  return [{ json: { source: 'WorldBank', commodity: 'Cereals', metric: 'no_data', value: 0, unit: 'N/A', period: 'N/A' } }];
}

return rows.map(r => ({ json: r }));
